// <auto-generated />
import { useCallback, useEffect, useRef, useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import type { UseQueryOptions, UseMutationOptions } from '@tanstack/react-query';
import { useApiService } from './useApiService';
import { ApiError } from '../errors/ApiError';
import type { CreateSubscriptionRequest, NotificationEvent, Subscription, Subscriptions } from '../models';

const notificationsKeys = {
  all: ['notifications'] as const,
  listSubscriptions: () => [...notificationsKeys.all, 'listSubscriptions'] as const,
  subscriptionById: (subscriptionId: string) => [...notificationsKeys.all, 'subscriptionById', subscriptionId] as const,
};

export { notificationsKeys };

/** List all notification subscriptions */
export function useListSubscriptions(options?: Omit<UseQueryOptions<Subscriptions, ApiError>, 'queryKey' | 'queryFn'>) {
  const api = useApiService();
  return useQuery({
    queryKey: notificationsKeys.listSubscriptions(),
    queryFn: async () => {
      const result = await api.notifications.listSubscriptions();
      if (result.status === 'ok') {
        return result.data;
      }
      throw new ApiError(
        result.response.status,
        result.response.statusText,
        'error' in result ? result.error.message : 'Request failed',
        result.response,
      );
    },
    ...options,
  });
}

/** Create a new subscription */
export function useCreateSubscription(options?: Omit<UseMutationOptions<Subscription, ApiError, CreateSubscriptionRequest>, 'mutationFn'>) {
  const api = useApiService();
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: async (body: CreateSubscriptionRequest) => {
      const result = await api.notifications.createSubscription(body);
      if (result.status === 'created') {
        return result.data;
      }
      throw new ApiError(
        result.response.status,
        result.response.statusText,
        'error' in result ? result.error.message : 'Request failed',
        result.response,
      );
    },
    ...options,
    onSuccess: (data, variables, onMutateResult, context) => {
      queryClient.invalidateQueries({ queryKey: notificationsKeys.all });
      options?.onSuccess?.(data, variables, onMutateResult, context);
    },
  });
}

/** Get subscription details */
export function useGetSubscriptionById(subscriptionId: string, options?: Omit<UseQueryOptions<Subscription, ApiError>, 'queryKey' | 'queryFn'>) {
  const api = useApiService();
  return useQuery({
    queryKey: notificationsKeys.subscriptionById(subscriptionId),
    queryFn: async () => {
      const result = await api.notifications.getSubscriptionById(subscriptionId);
      if (result.status === 'ok') {
        return result.data;
      }
      throw new ApiError(
        result.response.status,
        result.response.statusText,
        'error' in result ? result.error.message : 'Request failed',
        result.response,
      );
    },
    enabled: !!subscriptionId,
    ...options,
  });
}

/** Cancel a subscription */
export function useDeleteSubscription(options?: Omit<UseMutationOptions<void, ApiError, string>, 'mutationFn'>) {
  const api = useApiService();
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: async (subscriptionId: string) => {
      const result = await api.notifications.deleteSubscription(subscriptionId);
      if (result.status === 'noContent') {
        return;
      }
      throw new ApiError(
        result.response.status,
        result.response.statusText,
        'error' in result ? result.error.message : 'Request failed',
        result.response,
      );
    },
    ...options,
    onSuccess: (data, variables, onMutateResult, context) => {
      queryClient.invalidateQueries({ queryKey: notificationsKeys.all });
      options?.onSuccess?.(data, variables, onMutateResult, context);
    },
  });
}

/** Stream notifications in real-time */
export function useListNotificationsStream(query?: { topics?: string /* default: 'system,user,data' */ }, options?: { enabled?: boolean }) {
  const api = useApiService();
  const [items, setItems] = useState<readonly NotificationEvent[]>([]);
  const [status, setStatus] = useState<'idle' | 'streaming' | 'success' | 'error'>('idle');
  const [error, setError] = useState<Error | null>(null);
  const controllerRef = useRef<AbortController | null>(null);

  const cancel = useCallback(() => {
    controllerRef.current?.abort();
    controllerRef.current = null;
    setStatus('idle');
  }, []);

  const reset = useCallback(() => {
    cancel();
    setItems([]);
    setError(null);
  }, [cancel]);

  const enabled = options?.enabled !== false;
  const keyDep = JSON.stringify({ query });

  useEffect(() => {
    if (!enabled) return;

    const controller = new AbortController();
    controllerRef.current = controller;
    setStatus('streaming');
    setItems([]);
    setError(null);

    let buffer: NotificationEvent[] = [];
    let flushTimer: ReturnType<typeof setTimeout> | null = null;
    const flush = () => { flushTimer = null; if (!controller.signal.aborted) setItems(buffer.slice()); };
    (async () => {
      try {
        for await (const item of api.notifications.listNotifications(query, controller.signal)) {
          if (controller.signal.aborted) return;
          buffer.push(item);
          if (flushTimer === null) flushTimer = setTimeout(flush, 200);
        }
        if (!controller.signal.aborted) {
          if (flushTimer !== null) clearTimeout(flushTimer);
          setItems(buffer.slice());
          setStatus('success');
        }
      } catch (err) {
        if (controller.signal.aborted) return;
        if (err instanceof DOMException && err.name === 'AbortError') return;
        if (flushTimer !== null) clearTimeout(flushTimer);
        setItems(buffer.slice());
        setError(err as Error);
        setStatus('error');
      }
    })();

    return () => { controller.abort(); if (flushTimer !== null) clearTimeout(flushTimer); };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [enabled, keyDep]);

  return { items, status, error, cancel, reset };
}